export const unselectAllCredentials = () => (dispatch) =>
  dispatch({ type: types.CREDENTIALS_UNSELECT_ALL });

export const selectAllCredentials = () => (dispatch, getState) => {
  const credentialsList = selectCredentialsList(getState());
  dispatch({ type: types.CREDENTIALS_SELECT_ALL, credentialsList });
};

export const setCredentialField = (fieldName, value) => (dispatch) => {
  dispatch({ type: types.SET_CREDENTIAL_FIELD, field: fieldName, value });
};

export const getCredentials = () => async (dispatch, getState) => {
  dispatch({ type: types.CREDENTIALS_FETCHING });
  const queryParam = selectQueryParam('credentials', getState());
  try {
    const workspace = selectCurrentWorkspace(getState());
    const response = await api.credentials.getCredentials(workspace, queryParam);
    dispatch({
      type: types.CREDENTIALS_GET_SUCCESS,
      credentials: get(response, 'rows', []),
      count: get(response, 'count', 0)
    });
  } catch (e) {
    return dispatch({
      type: types.CREDENTIALS_GET_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const deleteCredentials = () => async (dispatch, getState) => {
  try {
    const workspace = selectCurrentWorkspace(getState());
    const seletedCredentials = selectCredentialsSelected(getState());
    const idsToDelete = {
      ids: seletedCredentials.map((cred) => cred.id)
    };
    const response = await api.credentials.deleteCredentials(workspace, idsToDelete);

    dispatch({
      type: types.CREDENTIALS_GET_SUCCESS,
      credentials: get(response, 'rows', [])
    });

    dispatch(unselectAllCredentials());
    dispatch(getCredentials());
  } catch (e) {
    return dispatch({
      type: types.CREDENTIALS_GET_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const deleteCredential = (id, isVulnDetail = false) => async (dispatch, getState) => {
  try {
    const workspace = selectCurrentWorkspace(getState());
    const idsToDelete = {
      ids: [id]
    };
    const response = await api.credentials.deleteCredentials(workspace, idsToDelete);

    dispatch({
      type: types.CREDENTIALS_GET_SUCCESS,
      credentials: get(response, 'rows', [])
    });

    if (isVulnDetail) {
      dispatch(getCredentialsByVuln());
    } else {
      dispatch(unselectAllCredentials());
      dispatch(getCredentials());
    }
  } catch (e) {
    return dispatch({
      type: types.CREDENTIALS_GET_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const getCredentialsByVuln = () => async (dispatch, getState) => {
  dispatch({ type: types.CREDENTIALS_FETCHING });
  try {
    const vulnId = selectVulnDetailId(getState());
    const workspace = selectCurrentWorkspace(getState());
    const page = selectPage('credentials', getState());
    const rowsPerPage = selectRowsPerPage('credentials', getState());
    const offset = (page - 1) * rowsPerPage;
    const response = await api.credentials.getCredentialsByVuln(
      workspace,
      vulnId,
      offset,
      rowsPerPage
    );
    dispatch({
      type: types.CREDENTIALS_GET_SUCCESS,
      credentials: get(response, 'rows', []),
      count: get(response, 'count', 0)
    });
  } catch (e) {
    return dispatch({
      type: types.CREDENTIALS_GET_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const getAvailableVulns = (search, setDropdown) => async (dispatch, getState) => {
  dispatch({ type: types.SET_AVAILABLE_VULNS_FETCHING });
  try {
    const workspace = selectCurrentWorkspace(getState());
    const queryParam = { filters: [{ name: 'name', op: 'ilike', val: `%${search}%` }] };
    const response = await api.credentials.getAvailableVulns(
      workspace,
      queryParam);
    setDropdown(get(response, 'vulnerabilities', []));
    dispatch({
      type: types.SET_AVAILABLE_VULNS,
      availableVulns: get(response, 'vulnerabilities', [])
    });
  } catch (e) {
    return dispatch({
      type: types.CREDENTIALS_GET_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const saveCredential = (isVulnDetail) => async (dispatch, getState) => {
  try {
    const workspaceSelected = selectCurrentWorkspace(getState());
    const credentialsList = selectCredentialsList(getState());
    const id = selectCredentialId(getState());
    const username = selectCredentialUsername(getState());
    const endpoint = selectCredentialClientEndpoint(getState());
    const password = selectCredentialPassword(getState());
    const leak_date = selectCredentialLeakDate(getState());
    const owned = selectCredentialOwned(getState());
    const vulnerabilities = selectCredentialLinkedVulns(getState());
    const vulnId = selectVulnDetailId(getState());

    const data = {
      username,
      endpoint,
      password,
      leak_date,
      owned,
      vulnerabilities: isVulnDetail ? [vulnId] : vulnerabilities.map((vuln) => vuln.id.toString())
    };

    let response = '';
    if (id) {
      response = await api.credentials.editCredential(
        workspaceSelected,
        id,
        data
      );

      const index = credentialsList.findIndex(
        (credential) => id === credential.id
      );

      const updatedCredential = {
        id,
        key: id,
        value: response
      };

      credentialsList[index] = { ...updatedCredential };

      dispatch({
        type: types.CREDENTIAL_UPDATE_SUCCESS,
        updatedCredential,
        credentialsList,
        isVulnDetail
      });
      dispatch(getCredentialsByVuln());
    } else {
      response = await api.credentials.createCredential(
        workspaceSelected,
        data
      );
      if (isVulnDetail) dispatch(getCredentialsByVuln());
      else dispatch(getCredentials());
    }
  } catch (e) {
    dispatch({
      type: types.SAVE_CREDENTIAL_FAIL,
      errorMessage: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const showCredentialDetail = (show, ws, id) => async (dispatch) => {
  try {
    let data = {};
    if (show) {
      dispatch({ type: types.FETCHING_CREDENTIAL });
      data = await api.credentials.fetchCredential(ws, id);
    }
    dispatch({ type: types.SHOW_CREDENTIAL_DETAIL, show, detail: data || {} });
  } catch (e) {
    dispatch({ type: types.CREDENTIALS_ERROR, error: get(e, 'message', 'There was an error, please try again') });
  }
};

export const updateCredential = (credentialBefore, field, value) => async (dispatch, getState) => {
  try {
    let credentialAfter = { ...credentialBefore };
    set(credentialAfter, field, value);
    const workspaceSelected = selectCurrentWorkspace(getState());
    const credentialsList = selectCredentialsList(getState());
    const data = { [field]: value };

    credentialAfter = await api.credentials.editCredential(
      workspaceSelected,
      credentialBefore.id,
      data
    );

    const index = credentialsList.findIndex(
      (credential) => credentialAfter.id === credential.id
    );

    credentialsList[index] = {
      id: credentialAfter.id,
      key: credentialAfter.id,
      value: credentialAfter
    };

    dispatch({
      type: types.CREDENTIAL_UPDATE_SUCCESS,
      credentialAfter,
      credentialsList
    });
  } catch (e) {
    return dispatch({
      type: types.CREDENTIAL_UPDATE_FAIL,
      error: get(e, 'message', 'There was an error, please try again')
    });
  }
};

export const showContextMenu = (show, XPos, YPos) => {
  return (dispatch, getState) => {
    const state = getState();
    const currentXPos = selectContextMenuXPos(state);
    const currentYPos = selectContextMenuYPos(state);
    const newXPos = XPos ? XPos + 1 : currentXPos;
    const newYPos = YPos ? YPos + 1 : currentYPos;

    dispatch({
      type: types.SHOW_CONTEXT_MENU,
      show,
      contextMenuXPos: newXPos,
      contextMenuYPos: newYPos
    });
  };
};

