export const uploadFile = (file, isVulnDetail) => async (dispatch, getState) => {
  try {
    dispatch({ type: types.CREDENTIALS_SET_UPLOAD_STATE, state: 'PROCESSING' });
    const ws = selectCurrentWorkspace(getState());
    const vulnId = selectVulnDetailId(getState());
    const response = await api.faraday.getSession();

    const cancelTokenSource = CancelToken.source();

    const fd = new FormData();
    fd.append('csrf_token', response.csrf_token);
    fd.append('file', file);
    if (isVulnDetail) fd.append('vulns_ids', vulnId.toString());

    await axios.post(`/_api/${CURRENT_API_VERSION}/ws/${ws}/credential/import_csv`, fd, {
      headers: {
        'Content-Type': 'multipart/form-data'
      },
      onUploadProgress: async (progressEvent) => {
        dispatch({
          type: types.CREDENTIALS_UPLOAD_CSV_UPDATE_PERCENT,
          progressEvent
        });
        if (
          Math.round((100 * progressEvent.loaded) / progressEvent.total) === 100
        ) {
          const index = getState().credentials.fileIndex - 1;
          dispatch({ type: types.CREDENTIALS_SET_CSV_FILE_INDEX, index });
        }
      },
      cancelToken: cancelTokenSource.token
    });

    const currentIndex = getState().credentials.fileIndex;
    if (currentIndex < 0) {
      dispatch({ type: types.CREDENTIALS_SET_UPLOAD_STATE, state: 'FINISHED' });
      dispatch(getWorkspaces());
      if (isVulnDetail) dispatch(getCredentialsByVuln());
      else dispatch(getCredentials());
    } else {
      dispatch({
        type: types.CREDENTIALS_SET_UPLOAD_STATE,
        state: 'PROCESSED'
      });
    }
  } catch (e) {
    if (!e.message || e.message !== 'cancel') {
      const currentIndex = getState().credentials.fileIndex;
      dispatch({
        type: types.CREDENTIALS_SET_NAME_INTO_FILE_ERROR_LIST_CSV,
        name: file.name
      });
      const filesCount = getState().credentials.filesToUpload.length;
      if (filesCount === 1) {
        dispatch({
          type: types.CREDENTIALS_UPLOAD_CSV_ERROR,
          error: "Couldn't upload your file. Please try again."
        });
      }
      if (currentIndex < 0) {
        dispatch({
          type: types.CREDENTIALS_SET_UPLOAD_STATE,
          state: 'FINISHED'
        });
        dispatch(getWorkspaces());
      } else {
        dispatch({
          type: types.CREDENTIALS_SET_UPLOAD_STATE,
          state: 'PROCESSED'
        });
      }
    } else {
      dispatch({ type: types.CREDENTIALS_CANCEL_REQUEST_UPLOAD_CSV });
    }
  }
};

const exportCsv = (result) => async (_, getState) => {
  const workspaceSelected = selectCurrentWorkspace(getState());
  const title = `SR-${workspaceSelected}`;

  const fileType =
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8';
  const fileExtension = '.csv';

  const data = new Blob([result], { type: fileType });
  FileSaver.saveAs(data, title + fileExtension);
};

export const downloadCredentials = (isVulnDetail = false) => async (dispatch, getState) => {
  const workspace = selectCurrentWorkspace(getState());
  const vulnId = selectVulnDetailId(getState());

  const state = getState();
  let advancedFilterQueryParam = [];
  try {
    advancedFilterQueryParam = selectAdvancedFilterQueryParam(
      state,
      'credentials',
      true
    );
  } catch (e) {
    dispatch(
      setFilterError(
        'credentials',
        'Syntax error. Please try again. For further help check our documentation'
      )
    );
  }

  const hasAdvancedFilter = advancedFilterQueryParam.filters.length > 0;
  const standardQueryParam = selectQueryParam('credentials', state, true);
  const queryParam = hasAdvancedFilter
    ? advancedFilterQueryParam
    : standardQueryParam;

  const downloadQueryParam = isVulnDetail ? { filters: [{ name: 'vulnerabilities', op: 'any', val: { name: 'id', op: 'eq', val: vulnId } }] } : queryParam;

  try {
    dispatch({ type: types.CREDENTIALS_EXPORT_CSV_REQUEST });
    const response = await api.credentials.exportCSV(workspace, downloadQueryParam);
    dispatch(exportCsv(response));
  } catch (err) {
    dispatch({ type: types.CREDENTIALS_EXPORT_CSV_FAILURE });
  }

  return dispatch({ type: types.CREDENTIALS_EXPORT_CSV_SUCCESS });
};

