export const selectWorkspacesQueryParam = (state) => {
  const entityFilters = get(state, 'filters.workspaces', null);
  const showGridView = selectShowGridViewContext(state);
  const rowsPerPageListView = selectRowsPerPageListView(state);
  const showInactive = selectShowInactive(state);
  const orderBySaved = selectOrderSaved(state);

  const defaultFilter = {
    name: 'active',
    op: '==',
    val: 'true'
  };

  if (entityFilters) {
    const {
      page, rowsPerPage, order_by, filters
    } = entityFilters;
    let rows = rowsPerPage;
    let order = order_by;
    if (!showGridView) rows = rowsPerPageListView;
    if (!isEmpty(orderBySaved)) order = [orderBySaved];
    const offset = (page - 1) * rows;

    let parsedFilter = { offset, limit: rows };
    const isOrdering = !isEmpty(order_by);
    const isFiltering = !isEmpty(filters);

    if (!isOrdering && !showInactive && !isFiltering) parsedFilter = Object.assign(parsedFilter, { order_by: order }, { filters: defaultFilter });
    if (isOrdering && !showInactive) parsedFilter = Object.assign(parsedFilter, { order_by: order }, { filters: defaultFilter });
    if (isOrdering && showInactive) parsedFilter = Object.assign(parsedFilter, { order_by: order });
    if (isFiltering && !showInactive) {
      if (filters[0].and) {
        const filtersObj = filters[0].and.map((item) => item);
        const newFilters = [...filtersObj, defaultFilter];
        parsedFilter = Object.assign(parsedFilter, { filters: [{ and: newFilters }] });
      } else {
        parsedFilter = Object.assign(parsedFilter, { filters: [{ and: [defaultFilter, filters[0]] }] });
      }
    }
    if (isFiltering && showInactive) parsedFilter = Object.assign(parsedFilter, { filters });
    return parsedFilter;
  }

  return [];
};

export const selectWorkspacesAdvancedFilterQueryParam = (state) => {
  const entityFilters = get(state, 'filters.workspaces', null);
  const showGridView = selectShowGridViewContext(state);
  const rowsPerPageListView = selectRowsPerPageListView(state);
  const showInactive = selectShowInactive(state);
  const val = showInactive ? 'false' : 'true';
  const {
    page, rowsPerPage, order_by
  } = entityFilters;
  let rows = rowsPerPage;
  if (!showGridView) rows = rowsPerPageListView;
  const advancedFilter = selectAdvancedFilter(state, 'workspaces');
  const defaultFilter = `{"name":"active","op":"==","val":${val}}`;
  const orderBy = JSON.stringify(order_by);
  const offset = (page - 1) * rows;

  let queryToParse;
  if (advancedFilter) queryToParse = `{"offset":${offset},"limit":${rows},"order_by":${orderBy},"filters":[${defaultFilter}, ${advancedFilter}]}`;
  else queryToParse = `{"offset":${offset},"limit":${rows},"order_by":${orderBy},"filters":[${defaultFilter}]}`;

  const parsedQuery = JSON.parse(queryToParse);
  return parsedQuery;
};

